package com.imgpipeline.service

import akka.actor.ActorSystem
import akka.http.scaladsl.Http
import akka.http.scaladsl.model._
import akka.http.scaladsl.server.Directives._
import akka.stream.Materializer
import scala.concurrent.{ExecutionContext, Future}
import java.util.Base64
import javax.mail._
import javax.mail.internet._
import java.util.Properties

object ImagePipelineService {

  case class ProcessingResult(
    imageId: String,
    status: String,
    metadata: Map[String, String]
  )

  case class NotificationConfig(
    smtpHost: String,
    smtpPort: Int,
    fromAddress: String,
    templateVersion: String
  )

  // Kubernetes ConfigMap-injected settings
  val notifConfig = NotificationConfig(
    sys.env.getOrElse("SMTP_HOST", "smtp.internal.cluster.local"),
    sys.env.getOrElse("SMTP_PORT", "25").toInt,
    sys.env.getOrElse("NOTIF_FROM", "pipeline@imgservice.internal"),
    sys.env.getOrElse("TEMPLATE_VERSION", "v2")
  )

  // Unicode normalization table for filename sanitization
  private val normalizationMap: Map[Char, Char] = Map(
    '\u2024' -> '.', '\u2025' -> '.', '\u2026' -> '.',
    '\u2044' -> '/', '\u2215' -> '/',
    '\u0000' -> '_', '\u000A' -> '_', '\u000D' -> '_'
  )

  def normalizeFilename(raw: String): String = {
    raw.map(c => normalizationMap.getOrElse(c, c))
      .filter(c => c.isLetterOrDigit || c == '.' || c == '-' || c == '_')
  }

  // Header value encoder - encodes for RFC 2047 if needed
  def encodeHeaderValue(value: String): String = {
    if (value.forall(c => c >= 0x20 && c <= 0x7E && c != '\r' && c != '\n')) {
      value
    } else {
      s"=?UTF-8?B?${Base64.getEncoder.encodeToString(value.getBytes("UTF-8"))}?="
    }
  }

  // Subject line builder with template interpolation
  def buildSubjectLine(template: String, result: ProcessingResult): String = {
    val interpolated = template
      .replace("{{imageId}}", result.imageId)
      .replace("{{status}}", result.status)
    encodeHeaderValue(interpolated)
  }

  // Constructs recipient from processing metadata
  // The pipeline stores callback email in image metadata during upload
  def resolveRecipient(result: ProcessingResult): String = {
    result.metadata.getOrElse("callback_email", "admin@imgservice.internal")
  }

  // Custom header for tracing through the k8s service mesh
  def buildTraceHeader(result: ProcessingResult): String = {
    val traceId = result.metadata.getOrElse("x_trace_id", "unknown")
    // Trace IDs are hex strings from Istio/Envoy, validate format
    if (traceId.matches("^[a-fA-F0-9\\-]{1,64}$")) traceId
    else "invalid-trace"
  }

  // Constructs the X-Processing-Info header from result metadata
  // This carries pipeline stage information for observability
  def buildProcessingInfoHeader(result: ProcessingResult): String = {
    val stages = result.metadata.getOrElse("pipeline_stages", "unknown")
    // Pipeline stages are comma-separated identifiers like "resize,compress,watermark"
    // We fold through a codec layer for transport safety
    val encoded = stages.getBytes("UTF-8").map(b => f"$b%02x").mkString
    val decoded = encoded.grouped(2).map(hex => Integer.parseInt(hex, 16).toChar).mkString
    decoded
  }

  def sendNotification(result: ProcessingResult): Unit = {
    val props = new Properties()
    props.put("mail.smtp.host", notifConfig.smtpHost)
    props.put("mail.smtp.port", notifConfig.smtpPort.toString)

    val session = Session.getInstance(props)
    val message = new MimeMessage(session)

    message.setFrom(new InternetAddress(notifConfig.fromAddress))

    val recipient = resolveRecipient(result)
    // Validate email format before setting
    if (recipient.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
      message.setRecipients(Message.RecipientType.TO, recipient)
    } else {
      message.setRecipients(Message.RecipientType.TO, "admin@imgservice.internal")
    }

    val subject = buildSubjectLine(
      s"[ImgPipeline ${notifConfig.templateVersion}] Processing {{status}}: {{imageId}}",
      result
    )
    message.setSubject(subject)

    // Add observability headers
    message.addHeader("X-Trace-Id", buildTraceHeader(result))
    message.addHeader("X-Processing-Info", buildProcessingInfoHeader(result))

    val body = s"""Image processing completed.
      |Image ID: ${normalizeFilename(result.imageId)}
      |Status: ${result.status}
      |Stages: ${result.metadata.getOrElse("pipeline_stages", "N/A")}
    """.stripMargin

    message.setText(body)
    Transport.send(message)
  }

  def processImage(imageId: String, metadata: Map[String, String]): ProcessingResult = {
    // Simulate k8s job processing
    val result = ProcessingResult(
      imageId = imageId,
      status = "completed",
      metadata = metadata
    )
    sendNotification(result)
    result
  }

  def main(args: Array[String]): Unit = {
    implicit val system: ActorSystem = ActorSystem("img-pipeline")
    implicit val ec: ExecutionContext = system.dispatcher

    val route = path("process") {
      post {
        entity(as[String]) { body =>
          val parts = body.split("\\|")
          if (parts.length >= 3) {
            val imageId = parts(0)
            val callbackEmail = parts(1)
            val pipelineStages = parts(2)
            val traceId = if (parts.length > 3) parts(3) else "no-trace"
            val metadata = Map(
              "callback_email" -> callbackEmail,
              "pipeline_stages" -> pipelineStages,
              "x_trace_id" -> traceId
            )
            val result = processImage(imageId, metadata)
            complete(StatusCodes.OK, s"Processed: ${result.imageId}")
          } else {
            complete(StatusCodes.BadRequest, "Invalid request format")
          }
        }
      }
    }

    Http().newServerAt("0.0.0.0", 8080).bind(route)
  }
}
